using System;
using System.Collections.Generic;

class Cart
{
    private readonly List<decimal> prices = new List<decimal>();
    public void Add(decimal p) { if (p < 0) throw new ArgumentException("negative"); prices.Add(p); }
    public decimal Total(decimal discountPct)
    {
        decimal sum = 0;
        foreach (var p in prices) sum += p;
        return sum - sum * discountPct / 100m;
    }
}

class Program
{
    static int failed = 0;
    static void Check(string name, decimal expected, decimal actual)
    {
        bool ok = expected == actual;
        if (!ok) failed++;
        Console.WriteLine((ok ? "PASS " : "FAIL ") + name + " expected=" + expected + " actual=" + actual);
    }

    static void Main()
    {
        // Name: Method_Scenario_ExpectedResult; one behaviour per test; no logic in the test body
        var cases = new[] {
            new { Name = "Total_NoDiscount_ReturnsSum", Pct = 0m, Expected = 30m },
            new { Name = "Total_TenPercent_ReturnsReducedSum", Pct = 10m, Expected = 27m },
            new { Name = "Total_FullDiscount_ReturnsZero", Pct = 100m, Expected = 0m },
        };
        foreach (var c in cases)   // "theory": same test, different data
        {
            var cart = new Cart();           // Arrange
            cart.Add(10m); cart.Add(20m);
            decimal total = cart.Total(c.Pct); // Act
            Check(c.Name, c.Expected, total);  // Assert
        }
        try { new Cart().Add(-1m); Console.WriteLine("FAIL Add_Negative_Throws"); failed++; }
        catch (ArgumentException) { Console.WriteLine("PASS Add_Negative_Throws"); }
        Console.WriteLine("failed=" + failed);
    }
}

using System;
using System.Reflection;

class Counter { public static int Instances; public int Value; public Counter() { Instances++; } }

class SampleTests
{
    public static int Constructed;
    public int shared;                      // state living in the test-class instance
    public SampleTests() { Constructed++; }
    public void TestA() { shared++; Console.WriteLine("  TestA sees shared=" + shared); }
    public void TestB() { shared++; Console.WriteLine("  TestB sees shared=" + shared); }
}

class Program
{
    static void Main()
    {
        MethodInfo[] tests = { typeof(SampleTests).GetMethod("TestA"), typeof(SampleTests).GetMethod("TestB") };

        Console.WriteLine("xUnit style: new instance per test");
        foreach (var m in tests)
        {
            var fresh = new SampleTests();   // constructor = setup, nothing leaks between tests
            m.Invoke(fresh, null);
        }
        Console.WriteLine("instances created: " + SampleTests.Constructed);

        Console.WriteLine("NUnit style: one instance per fixture");
        var one = new SampleTests();         // fields persist, [SetUp] must reset them
        foreach (var m in tests) m.Invoke(one, null);
        Console.WriteLine("instances created in total: " + SampleTests.Constructed);
    }
}

using System;
using System.Collections.Generic;

interface IRates { decimal Get(string cur); }
interface IMailer { void Send(string to, string body); }

class StubRates : IRates { public decimal Get(string cur) { return 2m; } }       // stub: canned answer
class SpyMailer : IMailer                                                        // spy: records calls
{
    public List<string> Sent = new List<string>();
    public void Send(string to, string body) { Sent.Add(to + ":" + body); }
}
class FakeRepo                                                                   // fake: working in-memory version
{
    private readonly Dictionary<int, string> rows = new Dictionary<int, string>();
    public void Save(int id, string v) { rows[id] = v; }
    public string Find(int id) { string v; return rows.TryGetValue(id, out v) ? v : null; }
}

class Checkout
{
    private readonly IRates rates; private readonly IMailer mailer; private readonly FakeRepo repo;
    public Checkout(IRates r, IMailer m, FakeRepo repo) { rates = r; mailer = m; this.repo = repo; }
    public decimal Pay(int orderId, decimal eur)
    {
        decimal usd = eur * rates.Get("USD");
        repo.Save(orderId, "paid " + usd);
        mailer.Send("a@example.test", "receipt " + usd);   // outbound side effect = real contract
        return usd;
    }
}

class Program
{
    static void Main()
    {
        var repo = new FakeRepo(); var spy = new SpyMailer();
        var total = new Checkout(new StubRates(), spy, repo).Pay(7, 50m);
        // state-based assertions on the fake, interaction assertion only on the email
        Console.WriteLine("returned=" + total);
        Console.WriteLine("repo state=" + repo.Find(7));
        Console.WriteLine("mails sent=" + spy.Sent.Count + " first=" + spy.Sent[0]);
    }
}

using System;
using System.Collections.Generic;

// Why a naive in-memory store is not a database: it ignores constraints.
class NaiveStore
{
    public List<string> Rows = new List<string>();
    public void Insert(string email) { Rows.Add(email); }               // never rejects duplicates
    public int CountCI(string e) { return Rows.FindAll(r => r == e).Count; } // case-sensitive compare
}

class UniqueStore                                                       // behaves like a UNIQUE index, case-insensitive collation
{
    private readonly HashSet<string> keys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    public void Insert(string email)
    {
        if (!keys.Add(email)) throw new InvalidOperationException("UNIQUE constraint failed: " + email);
    }
}

class Program
{
    static void Main()
    {
        var naive = new NaiveStore();
        naive.Insert("Ann@x.test"); naive.Insert("Ann@x.test");
        Console.WriteLine("naive rows=" + naive.Rows.Count + " (duplicate accepted, bug hidden)");
        Console.WriteLine("naive match for 'ann@x.test'=" + naive.CountCI("ann@x.test") + " (case-sensitive)");

        var real = new UniqueStore();
        real.Insert("Ann@x.test");
        try { real.Insert("ann@X.test"); Console.WriteLine("accepted"); }
        catch (InvalidOperationException e) { Console.WriteLine("real store: " + e.Message); }
    }
}

using System;
using System.Collections.Generic;

enum State { Detached, Added, Unchanged, Modified, Deleted }

class Entry
{
    public int Id; public string Name; public string Original; public State State;
}

class Tracker
{
    public List<Entry> Entries = new List<Entry>();
    public Entry Query(int id, string name)           // query results are tracked as Unchanged + snapshot
    { var e = new Entry { Id = id, Name = name, Original = name, State = State.Unchanged }; Entries.Add(e); return e; }
    public Entry Add(string name)
    { var e = new Entry { Name = name, State = State.Added }; Entries.Add(e); return e; }
    public void Remove(Entry e)
    { e.State = e.State == State.Added ? State.Detached : State.Deleted; }   // Added -> just forget it
    public void DetectChanges()                       // compare current values with snapshot
    { foreach (var e in Entries) if (e.State == State.Unchanged && e.Name != e.Original) e.State = State.Modified; }
    public int SaveChanges()
    {
        DetectChanges(); int n = 0;
        foreach (var e in Entries)
        {
            if (e.State == State.Added) { Console.WriteLine("  INSERT " + e.Name); n++; }
            else if (e.State == State.Modified) { Console.WriteLine("  UPDATE " + e.Original + " -> " + e.Name); n++; }
            else if (e.State == State.Deleted) { Console.WriteLine("  DELETE " + e.Name); n++; }
        }
        foreach (var e in Entries)                    // accept changes
        {
            if (e.State == State.Deleted) e.State = State.Detached;
            else if (e.State != State.Detached) { e.State = State.Unchanged; e.Original = e.Name; }
        }
        return n;
    }
}

class Program
{
    static void Main()
    {
        var t = new Tracker();
        var a = t.Query(1, "Ann"); var b = t.Query(2, "Bob"); t.Query(3, "Cy");
        a.Name = "Anna";            // edit tracked entity
        t.Remove(b);                // mark deleted
        var tmp = t.Add("Temp"); t.Remove(tmp);   // added then removed: nothing to write
        t.Add("Dee");
        Console.WriteLine("rows written = " + t.SaveChanges());
        Console.WriteLine("second save writes = " + t.SaveChanges());
    }
}

using System;
using System.Collections.Generic;

class Program
{
    // Available versions of a package, and requirements (minimums) from the graph
    static readonly Version[] Available = { new Version(1, 0, 0), new Version(1, 2, 0), new Version(1, 5, 0), new Version(2, 0, 0) };

    static Version LowestApplicable(Version min)
    {
        foreach (var v in Available) if (v >= min) return v;   // sorted: first one that satisfies
        return null;
    }

    static void Main()
    {
        // "Version=1.2.0" means >= 1.2.0, and NuGet picks the LOWEST such version
        Console.WriteLine("range >=1.2.0 picks " + LowestApplicable(new Version(1, 2, 0)) + " (1.5.0 and 2.0.0 also exist)");

        // Two cousin branches require >=1.2.0 and >=1.4.0: the lowest version meeting both
        var reqs = new List<Version> { new Version(1, 2, 0), new Version(1, 4, 0) };
        Version max = reqs[0];
        foreach (var r in reqs) if (r > max) max = r;
        Console.WriteLine("cousins " + string.Join(", ", reqs) + " -> " + LowestApplicable(max));

        // Direct dependency wins, but downgrading below a transitive minimum is an error (NU1605)
        var direct = new Version(1, 0, 0); var transitive = new Version(1, 2, 0);
        Console.WriteLine(direct < transitive ? "direct 1.0.0 < transitive minimum 1.2.0 -> NU1605 downgrade error"
                                              : "direct ok");
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static Dictionary<string, string> props = new Dictionary<string, string>();

    // $(Name) is expanded at the moment of assignment; undefined -> empty string
    static string Expand(string s)
    {
        int i;
        while ((i = s.IndexOf("$(")) >= 0)
        {
            int j = s.IndexOf(')', i);
            string name = s.Substring(i + 2, j - i - 2);
            string v; props.TryGetValue(name, out v);
            s = s.Substring(0, i) + (v ?? "") + s.Substring(j + 1);
        }
        return s;
    }
    static void Set(string name, string value, bool isGlobal)
    {
        if (globals.Contains(name) && !isGlobal) { Console.WriteLine("  ignored: " + name + " is a global property"); return; }
        props[name] = Expand(value);
        Console.WriteLine("  " + name + " = '" + props[name] + "'");
    }
    static HashSet<string> globals = new HashSet<string>();

    static void Main()
    {
        Console.WriteLine("evaluation, top to bottom:");
        Set("Config", "Release", true); globals.Add("Config");   // like dotnet build -p:Config=Release
        Set("Out", "bin/$(Config)/$(Tfm)", false);               // Tfm is not defined yet -> empty
        Set("Tfm", "net8.0", false);
        Set("Config", "Debug", false);                           // cannot override a global
        Set("Tfm", "net9.0", false);                             // later definition wins (like an SDK .targets file)
        Console.WriteLine("final Tfm = " + props["Tfm"] + ", Out = " + props["Out"]);
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static bool IsAdult(int age, int limit) { return age >= limit; }
    // Mutants: small deliberate bugs, as Stryker.NET would generate
    static bool Mutant1(int age, int limit) { return age > limit; }
    static bool Mutant2(int age, int limit) { return age <= limit; }

    delegate bool Fn(int a, int l);
    static int Run(Fn f, int[][] tests)   // returns number of failing tests
    {
        int fails = 0;
        foreach (var t in tests) if (f(t[0], t[1]) != (t[2] == 1)) fails++;
        return fails;
    }

    static void Main()
    {
        // coverage is 100% for both suites, but only one checks the boundary
        int[][] weak = { new[] { 30, 18, 1 }, new[] { 5, 18, 0 } };
        int[][] strong = { new[] { 30, 18, 1 }, new[] { 5, 18, 0 }, new[] { 18, 18, 1 } };
        var mutants = new Dictionary<string, Fn> { { "age > limit", Mutant1 }, { "age <= limit", Mutant2 } };

        foreach (var suite in new[] { "weak", "strong" })
        {
            var tests = suite == "weak" ? weak : strong;
            int killed = 0;
            foreach (var m in mutants)
            {
                bool dead = Run(m.Value, tests) > 0;   // killed = some test fails
                if (dead) killed++;
                Console.WriteLine(suite + " suite, mutant '" + m.Key + "': " + (dead ? "killed" : "SURVIVED"));
            }
            Console.WriteLine(suite + " mutation score = " + killed + "/" + mutants.Count);
        }
    }
}
